'use strict';
(() => {
const $ = s => document.querySelector(s);
const canvas=$('#garden'),ctx=canvas.getContext('2d'),W=1200,H=1080;
const sprites=new Map(), thumbs=new Map(), sources={mushrooms:['assets/mushrooms.webp',3,2],visitors:['assets/visitors.webp',3,2],critters:['assets/critters.webp',3,3],sky:['assets/sky.webp',3,2]};
const catalog=[
{id:'toadstool',name:'Toadstool',group:'mushrooms',sheet:'mushrooms',cell:0,size:245},
{id:'wavy',name:'Wavy',group:'mushrooms',sheet:'mushrooms',cell:1,size:265},
{id:'ruffles',name:'Ruffles',group:'mushrooms',sheet:'mushrooms',cell:2,size:220},
{id:'twins',name:'Twins',group:'mushrooms',sheet:'mushrooms',cell:3,size:185},
{id:'curly',name:'Curly',group:'mushrooms',sheet:'mushrooms',cell:4,size:225},
{id:'bell',name:'Ghost cap',group:'mushrooms',sheet:'mushrooms',cell:5,size:235},
{id:'cat',name:'Cat',group:'animals',sheet:'visitors',cell:0,size:190},
{id:'frog',name:'Frog',group:'animals',sheet:'visitors',cell:1,size:145},
{id:'snail',name:'Snail',group:'animals',sheet:'visitors',cell:2,size:130},
{id:'bunny',name:'Bunny',group:'animals',sheet:'critters',cell:0,size:190},
{id:'raccoon',name:'Raccoon',group:'animals',sheet:'critters',cell:1,size:200},
{id:'bat',name:'Bat',group:'animals',sheet:'critters',cell:2,size:165},
{id:'possum',name:'Possum',group:'animals',sheet:'critters',cell:3,size:180},
{id:'shrimp',name:'Shrimp',group:'animals',sheet:'critters',cell:4,size:140},
{id:'raven',name:'Raven',group:'animals',sheet:'critters',cell:5,size:190},
{id:'spider',name:'Spider',group:'animals',sheet:'critters',cell:6,size:115},
{id:'ghost',name:'Ghost',group:'spooky',sheet:'visitors',cell:3,size:180},
{id:'skull',name:'Skull',group:'spooky',sheet:'visitors',cell:4,size:130},
{id:'pumpkin',name:'Pumpkin',group:'spooky',sheet:'visitors',cell:5,size:160},
{id:'mothman',name:'Mothman',group:'spooky',sheet:'critters',cell:7,size:240},
{id:'jack',name:'Jack-o’-lantern',group:'spooky',sheet:'critters',cell:8,size:160},
{id:'web',name:'Spiderweb',group:'spooky',sheet:'sky',cell:4,size:200}];
const customRects={critters:[[10,8,407,406],[428,35,398,373],[826,64,428,310],[7,461,420,326],[438,420,389,381],[871,410,378,404],[7,844,406,385],[410,799,438,444],[850,817,400,415]],sky:[[48,38,426,422],[591,31,395,438],[1174,23,266,450],[39,523,447,440],[521,486,491,499],[1050,486,452,537]]};
const byId=Object.fromEntries(catalog.map(v=>[v.id,v]));
const palettes={candy:{name:'Candy',bg:'#fff6ec',wash:'#fae5e8',ink:'#38304c',accent:'#e76f86',hue:0},bog:{name:'Bog',bg:'#f6fae9',wash:'#e3ecd0',ink:'#33463a',accent:'#6c9368',hue:62},dusk:{name:'Dusk',bg:'#f3f1fc',wash:'#e4def4',ink:'#423251',accent:'#a57abd',hue:300}};
let state={items:[],palette:'candy',moon:'crescent',weather:[],seed:8921},history=[],selected='toadstool',category='mushrooms',ready=false,counter=0,keyboard=false,cursor={x:600,y:650},toastTimer;
const snapshot=()=>JSON.parse(JSON.stringify(state));
function remember(){history.push(snapshot());if(history.length>60)history.shift();}
function rand(seed){let n=seed>>>0;return()=>{n=(Math.imul(n,1664525)+1013904223)>>>0;return n/4294967296;};}
function notify(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600);}
function dimensions(item){const s=sprites.get(item.id),m=Math.max(s.width,s.height);return {w:s.width/m*item.size,h:s.height/m*item.size};}
function makeItem(id,x,y,size){const c=byId[id],item={id,x,y,size:size||c.size*(.88+Math.random()*.22),flip:Math.random()<.25};if(ready){const d=dimensions(item);item.x=Math.max(d.w/2+10,Math.min(W-d.w/2-10,x));item.y=Math.max(d.h+15,Math.min(H-38,y));}return item;}
function seedGarden(seed){const r=rand(seed);const items=[];const placements=[['wavy',.26,.43,250],['bell',.57,.40,210],['toadstool',.76,.54,295],['ruffles',.43,.58,225],['curly',.17,.67,275],['twins',.6,.68,225],['toadstool',.86,.77,240],['bell',.37,.83,280],['wavy',.65,.93,290],['ruffles',.16,.91,195],['twins',.86,.94,165],['cat',.51,.91,175],['frog',.31,.64,130],['snail',.76,.90,135],['ghost',.46,.30,150],['bunny',.72,.72,150],['pumpkin',.45,.73,140]];for(const [id,x,y,size]of placements){const next=counter?catalog[Math.floor(r()*catalog.length)].id:id;const it=makeItem(next,(x+(r()-.5)*.025)*W,(y+(r()-.5)*.025)*H,size);it.flip=r()<.28;items.push(it);}return items;}
function stamp(id,x,y){if(!ready)return;if(!byId[id])throw Error('Unknown garden item');if(state.items.length>=100){notify('A very full garden! Undo or clear a little space.');return false;}remember();state.items.push(makeItem(id,x,y));$('#canvasHint').classList.add('hidden');render();return true;}
function renderSprites(){const el=$('#stamps');el.className='stamps'+(catalog.filter(v=>v.group===category).length>6?' many':'');el.replaceChildren();for(const item of catalog.filter(v=>v.group===category)){const b=document.createElement('button');b.className='stamp'+(item.id===selected?' active':'');b.setAttribute('aria-pressed',String(item.id===selected));b.setAttribute('aria-label','Place '+item.name.toLowerCase());b.dataset.id=item.id;const im=document.createElement('img');im.alt='';im.draggable=false;im.src=thumbs.get(item.id)||'';b.append(im,document.createTextNode(item.name));b.addEventListener('click',()=>{selected=item.id;renderSprites();$('#canvasHint').textContent='Tap to place '+(item.id==='jack'?'a jack-o’-lantern':item.name.toLowerCase());$('#canvasHint').classList.remove('hidden');});el.append(b);}}
function drawSprite(target,id,x,y,size,flip=false,hue=0){const s=sprites.get(id);if(!s)return;const scale=size/Math.max(s.width,s.height);target.save();target.translate(x,y);if(flip)target.scale(-1,1);if(hue)target.filter=`hue-rotate(${hue}deg)`;target.drawImage(s,-s.width*scale/2,-s.height*scale,s.width*scale,s.height*scale);target.restore();}
function draw(target,includeCursor=false){const p=palettes[state.palette],r=rand(state.seed);target.clearRect(0,0,W,H);target.fillStyle=p.bg;target.fillRect(0,0,W,H);const g=target.createRadialGradient(570,650,60,580,650,620);g.addColorStop(0,p.wash);g.addColorStop(1,p.bg);target.fillStyle=g;target.fillRect(0,0,W,H);
// Sparse paper speckles are deliberately quiet behind the illustrations.
for(let i=0;i<180;i++){target.globalAlpha=.15+r()*.12;target.fillStyle=p.ink;target.beginPath();target.arc(30+r()*(W-60),35+r()*(H-70),.6+r()*1.1,0,Math.PI*2);target.fill();}target.globalAlpha=1;
if(state.moon!=='none')drawSprite(target,'moon-'+state.moon,990,250,155,false,0);
if(state.weather.includes('lightning'))drawSprite(target,'lightning',235,280,240,false,p.hue);
for(const item of [...state.items].sort((a,b)=>a.y-b.y))drawSprite(target,item.id,item.x,item.y,item.size,item.flip,p.hue);
if(state.weather.includes('rain')){target.strokeStyle=p.ink;target.lineWidth=2;target.globalAlpha=.22;for(let i=0;i<140;i++){let x=r()*W,y=r()*H;target.beginPath();target.moveTo(x,y);target.lineTo(x-8,y+22);target.stroke();}target.globalAlpha=1;}
if(state.weather.includes('snow')){for(let i=0;i<150;i++){target.fillStyle=i%3?'#fffefa':p.accent;target.globalAlpha=i%3?.9:.5;target.beginPath();target.arc(r()*W,r()*H,1.8+r()*4,0,Math.PI*2);target.fill();}target.globalAlpha=1;}
if(state.weather.includes('fog')){for(let i=0;i<3;i++){const y=H*(.42+i*.22),fg=target.createLinearGradient(0,y-150,0,y+120);fg.addColorStop(0,'rgba(255,255,255,0)');fg.addColorStop(.52,'rgba(255,255,255,.53)');fg.addColorStop(1,'rgba(255,255,255,0)');target.fillStyle=fg;target.fillRect(0,y-150,W,270);}}
if(!state.items.length){target.fillStyle=p.ink;target.textAlign='center';target.font='italic 37px Georgia';target.fillText('A little room for something strange.',W/2,H/2);target.font='25px Arial';target.fillText('Pick an oddity and tap to plant it.',W/2,H/2+50);}
if(includeCursor&&keyboard){target.strokeStyle=p.ink;target.lineWidth=2;target.setLineDash([7,7]);target.beginPath();target.arc(cursor.x,cursor.y,27,0,Math.PI*2);target.stroke();target.setLineDash([]);}}
function render(){if(!ready)return;draw(ctx,true);$('#count').textContent=state.items.length+' little '+(state.items.length===1?'oddity':'oddities');$('#undo').disabled=!history.length;$('#clear').disabled=!state.items.length&&state.moon==='none'&&!state.weather.length;$('#paletteName').textContent=palettes[state.palette].name;document.querySelectorAll('[data-palette]').forEach(b=>{b.classList.toggle('active',b.dataset.palette===state.palette);b.setAttribute('aria-pressed',String(b.dataset.palette===state.palette));});$('#moon').value=state.moon;document.querySelectorAll('[data-weather]').forEach(b=>b.setAttribute('aria-pressed',String(state.weather.includes(b.dataset.weather))));const phrases={mushrooms:'Mushrooms make excellent company.',animals:'All the best gardens have visitors.',spooky:'A little haunting is good for the soul.'};$('#caption').textContent=phrases[category];}
function choosePalette(key){if(!palettes[key])throw Error('Unknown palette');if(state.palette!==key){remember();state.palette=key;render();}return {palette:state.palette};}
function changeSky(moon,weather){const allowedMoons=['none','full','crescent','half','blood'],allowedWeather=['rain','snow','fog','lightning'];if(!allowedMoons.includes(moon)||!Array.isArray(weather)||weather.some(x=>!allowedWeather.includes(x)))throw Error('Invalid sky settings');remember();state.moon=moon;state.weather=[...new Set(weather)];render();return {moon:state.moon,weather:state.weather};}
function undo(){if(!history.length)return;state=history.pop();render();notify('One little step back.');}
function surprise(){if(!ready)return;remember();counter++;state.seed=Math.floor(Math.random()*100000);state.items=seedGarden(state.seed);render();notify('A fresh batch of peculiar company.');}
function clear(){if(!ready)return;remember();state.items=[];state.moon='none';state.weather=[];render();notify('A clean patch. Undo brings it all back.');}
function save(){if(!ready)return;const out=document.createElement('canvas');out.width=W;out.height=H+130;const c=out.getContext('2d');c.fillStyle=palettes[state.palette].bg;c.fillRect(0,0,out.width,out.height);const art=document.createElement('canvas');art.width=W;art.height=H;draw(art.getContext('2d'));c.drawImage(art,0,0);c.strokeStyle=palettes[state.palette].ink;c.lineWidth=1;c.beginPath();c.moveTo(50,H+12);c.lineTo(W-50,H+12);c.stroke();c.fillStyle=palettes[state.palette].ink;c.font='44px Georgia';c.fillText('The Odd Garden',50,H+78);c.font='18px Arial';c.textAlign='right';c.fillText('A LITTLE PLACE FOR STRANGE THINGS',W-50,H+71);out.toBlob(blob=>{if(!blob){notify('That picture couldn’t be saved. Please try again.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='the-odd-garden.png';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('Your garden picture is ready to save.');},'image/png');}
canvas.addEventListener('pointerup',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;const bounds=canvas.getBoundingClientRect();keyboard=false;stamp(selected,(e.clientX-bounds.left)/bounds.width*W,(e.clientY-bounds.top)/bounds.height*H);});
canvas.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter',' '].includes(e.key)){e.preventDefault();keyboard=true;if(e.key==='ArrowUp')cursor.y-=35;if(e.key==='ArrowDown')cursor.y+=35;if(e.key==='ArrowLeft')cursor.x-=35;if(e.key==='ArrowRight')cursor.x+=35;cursor.x=Math.max(30,Math.min(W-30,cursor.x));cursor.y=Math.max(100,Math.min(H-30,cursor.y));if(e.key==='Enter'||e.key===' ')stamp(selected,cursor.x,cursor.y);else render();}});canvas.addEventListener('blur',()=>{keyboard=false;render();});
document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;selected=catalog.find(v=>v.group===category).id;document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderSprites();render();}));
document.querySelectorAll('[data-palette]').forEach(b=>b.addEventListener('click',()=>choosePalette(b.dataset.palette)));
$('#moon').addEventListener('change',e=>changeSky(e.target.value,state.weather));document.querySelectorAll('[data-weather]').forEach(b=>b.addEventListener('click',()=>{const effect=b.dataset.weather;changeSky(state.moon,state.weather.includes(effect)?state.weather.filter(x=>x!==effect):[...state.weather,effect]);}));$('#undo').addEventListener('click',undo);$('#clear').addEventListener('click',clear);$('#surprise').addEventListener('click',surprise);$('#save').addEventListener('click',save);
function loadSheet(key,[src,cols,rows]){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{const cw=Math.floor(im.width/cols),ch=Math.floor(im.height/rows);for(let cell=0;cell<cols*rows;cell++){const [sx,sy,sw,sh]=customRects[key]?.[cell]||[(cell%cols)*cw,Math.floor(cell/cols)*ch,cw,ch];const tile=document.createElement('canvas');tile.width=sw;tile.height=sh;const tc=tile.getContext('2d',{willReadFrequently:true});tc.drawImage(im,sx,sy,sw,sh,0,0,sw,sh);const pixels=tc.getImageData(0,0,sw,sh).data;let minX=sw,minY=sh,maxX=0,maxY=0;for(let y=0;y<sh;y++)for(let x=0;x<sw;x++)if(pixels[(y*sw+x)*4+3]>25){minX=Math.min(x,minX);maxX=Math.max(x,maxX);minY=Math.min(y,minY);maxY=Math.max(y,maxY);}if(maxX<minX||maxY<minY)throw Error('Empty illustration');const cut=document.createElement('canvas');cut.width=maxX-minX+1;cut.height=maxY-minY+1;cut.getContext('2d').drawImage(tile,minX,minY,cut.width,cut.height,0,0,cut.width,cut.height);const entry=catalog.find(v=>v.sheet===key&&v.cell===cell);const id=entry?entry.id:key==='sky'?['moon-full','moon-crescent','moon-half','moon-blood','web','lightning'][cell]:null;if(id){sprites.set(id,cut);thumbs.set(id,cut.toDataURL('image/png'));}}resolve();};im.onerror=()=>reject(Error('Illustrations could not load'));im.src=src;});}
function registerTools(){const mc=document.modelContext;if(!mc?.registerTool)return;const life=new AbortController();const register=t=>{try{Promise.resolve(mc.registerTool(t,{signal:life.signal})).catch(()=>{});}catch{}};register({name:'read_garden',title:'Read garden',description:'Read the current garden items, palette, moon, and weather.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>snapshot()});register({name:'plant_garden_items',title:'Plant garden items',description:'Add illustrated items to the visible garden at coordinates from 0 to 1.',inputSchema:{type:'object',properties:{items:{type:'array',minItems:1,maxItems:20,items:{type:'object',properties:{id:{type:'string',enum:catalog.map(c=>c.id)},x:{type:'number',minimum:0,maximum:1},y:{type:'number',minimum:0,maximum:1}},required:['id','x','y'],additionalProperties:false}}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Array.isArray(input.items)||input.items.length<1||input.items.length>20||input.items.some(v=>!byId[v.id]||!Number.isFinite(v.x)||!Number.isFinite(v.y)||v.x<0||v.x>1||v.y<0||v.y>1))throw Error('Invalid garden items');if(state.items.length+input.items.length>100)throw Error('Garden limit is 100 items');remember();for(const v of input.items)state.items.push(makeItem(v.id,v.x*W,v.y*H));render();return {itemCount:state.items.length};}});register({name:'set_garden_mood',title:'Set garden mood',description:'Change the visible garden color palette, moon, and weather.',inputSchema:{type:'object',properties:{palette:{type:'string',enum:Object.keys(palettes)},moon:{type:'string',enum:['none','full','crescent','half','blood']},weather:{type:'array',items:{type:'string',enum:['rain','snow','fog','lightning']}}},required:['palette','moon','weather'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!palettes[input.palette]||!['none','full','crescent','half','blood'].includes(input.moon)||!Array.isArray(input.weather)||input.weather.some(x=>!['rain','snow','fog','lightning'].includes(x)))throw Error('Invalid garden mood');remember();state.palette=input.palette;state.moon=input.moon;state.weather=[...new Set(input.weather)];render();return {palette:state.palette,moon:state.moon,weather:state.weather};}});window.addEventListener('pagehide',()=>life.abort(),{once:true});}
Promise.all(Object.entries(sources).map(([k,v])=>loadSheet(k,v))).then(()=>{ready=true;state.items=seedGarden(state.seed);$('#loading').classList.add('gone');renderSprites();render();registerTools();}).catch(()=>{$('#loading').textContent='The little creatures couldn’t load. Refresh to try again.';$('#count').textContent='Garden unavailable';document.querySelectorAll('button,select').forEach(b=>b.disabled=true);});
})();
